def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    total_sum = sum(a)

    if total_sum == 1:
        return '-1\n'

    def get_cost(k):
        """Calculate minimum moves to make all boxes divisible by k"""
        cost = 0
        prefix_mod = 0
        for x in a:
            prefix_mod = (prefix_mod + x) % k
            cost += prefix_mod
        return cost

    # Edge case: single box with 1 chocolate - impossible
    if n == 1 and a[0] == 1:
        return '-1\n'

    # Find all divisors of total_sum
    def get_divisors(num):
        divisors = []
        i = 2
        while i * i <= num:
            if num % i == 0:
                divisors.append(i)
                if i * i != num:
                    divisors.append(num // i)
            i += 1
        # Only add total_sum if it has at least 2 factors
        if total_sum > 1:
            divisors.append(total_sum)
        return divisors

    divisors = get_divisors(total_sum)

    if not divisors:
        return '-1\n'

    min_moves = float('inf')

    for k in divisors:
        moves = get_cost(k)
        if moves < min_moves:
            min_moves = moves

    return f'{min_moves}\n' if min_moves != float('inf') else '-1\n'

