    # (without using any ? to break them)
    def max_n_consecutive(episode_str):
        return max(episode_str.count('N') * (episode_str.replace('N', 'Y').count('Y') == 0), 
                   max([len(block) for block in episode_str.replace('Y', ' ').split() if block and block == 'N'] or [0]))

    # More direct check: scan original string for N runs that are already too long
    current_n = 0
    for char in s:
