    # Now check if there's a configuration where max N run = k
    # We need both:
    # 1. There exists a valid configuration where max N run <= k
    # 2. There exists a valid configuration where max N run >= k
    # And we can achieve exactly k

    # Find maximum possible consecutive N's (all ? -> N)
    s_all_N = s.replace('?', 'N')
    max_possible = 0
