class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []
        self.original_flow = [[] for _ in range(n)]  # For reconstructing flow

    def add_edge(self, u, v, cap):
        # Forward edge: [v, cap, rev_index]
        self.graph[u].append((v, cap, len(self.graph[v]), float('inf')))
        # Store original capacity for reconstruction
        self.original_flow[u].append([v, cap, len(self.graph[v])])
        # Backward edge: [u, 0, rev_index] (no capacity from v to u initially)
        self.graph[v].append((u, 0, len(self.graph[u]) - 1, 0))

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, rev_idx in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
