    # f = number of positions where position i has -1 AND value i is missing
    # These are forbidden assignments we must exclude
    f = 0
    for pos in positions_with_minus_one:
        if pos in missing_values:
            f += 1

    # Precompute factorials for computing combinations
    fact = [1] * (k + 1)
    for i in range(1, k + 1):
