def solution(input_text):
    lines = input_text.strip().split('\n')
    n, k = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    special_pairs = []
    for i in range(k):
        special_pairs.append(tuple(map(int, lines[2 + i].split())))

    # Build prerequisite graph
    # in_degree[i] = number of prerequisites for topic i+1
    in_degree = [0] * (n + 1)
    adj = [[] for _ in range(n + 1)]

    for i in range(1, n + 1):
        prereq = p[i - 1]
        if prereq != 0:
            in_degree[i] += 1
            adj[prereq].append(i)

    # For special pairs, we'll track chains
    # next_in_chain[x] = y means y must come right after x in a special pair
    next_in_chain = [0] * (n + 1)
    has_chain_parent = [False] * (n + 1)

    for x, y in special_pairs:
        next_in_chain[x] = y
        has_chain_parent[y] = True

    # rel_in_degree tracks if we're in a chain and position in chain matters
    # if x is start of a chain, rel_in_degree[x] = 0, otherwise use actual in_degree

    # For topics in chains, we treat chain as partially satisfying prerequisites
    # A topic can be processed when:
    # 1. It's not in a chain OR its in_degree is 0 AND its chain_parent is processed
    # 2. It's in a chain: only add to available when its chain_parent is processed AND in_degree is 0

    available = set()

    for i in range(1, n + 1):
        if in_degree[i] == 0:
            available.add(i)

    result = []

    while len(result) < n:
        if not available:
            return "0"

        # Skip topics that have chain parent not yet in result
        temp_available = set()
        for topic in available:
            # If topic is part of a chain (not root of chain) and parent not processed, skip
            if has_chain_parent[topic] and topic not in result:
                continue
            temp_available.add(topic)

        available = temp_available

        if not available:
            return "0"

        # Get first available topic
        current = available.pop()
        result.append(current)

        # Follow chain
        while next_in_chain[current] != 0:
            next_topic = next_in_chain[current]
            # Check if next_topic is available
            if in_degree[next_topic] == 0 and has_chain_parent[next_topic] and next_topic not in result:
                available.add(next_topic)
            else:
                # Can't continue chain - check if next_topic prerequisites are not met
                if in_degree[next_topic] > 0 or not has_chain_parent[next_topic]:
                    break

        # Add newly available topics from dependencies
        for dep in adj[current]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                available.add(dep)

    # Verify the result
    if len(result) != n:
        return "0"

    # Check if all prerequisites are satisfied
    pos = {topic: i for i, topic in enumerate(result)}
    for i in range(1, n + 1):
        prereq = p[i - 1]
        if prereq != 0 and pos[prereq] >= pos[i]:
            return "0"

    # Check all special pairs
    for x, y in special_pairs:
        if pos[x] + 1 != pos[y]:
            return "0"

    return ' '.join(map(str, result)) if result else "0"

