def find_permutation(n, k):
    used = [False] * (n + 1)
    result = [0] * n

    def backtrack(pos):
        if pos > n:
            return True

        # Try values in increasing order for lexicographically smallest
        for v in range(1, n + 1):
            if not used[v] and abs(v - pos) >= k:
                used[v] = True
                result[pos - 1] = v

                if backtrack(pos + 1):
                    return True

                used[v] = False

        return False

    if backtrack(1):
        return " ".join(map(str, result))
    else:
        return "-1"


