        parts = lines[i].split()
        u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
        pre_assigned.append((u, v, w))
        edge_set.add((min(u, v), max(u, v)))

    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            if rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            elif rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            else:
                parent[root_i] = root_j
                rank[root_j] += 1
            return True
        return False

    all_edges = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if (i, j) not in edge_set:
                all_edges.append((0, i, j))

    all_edges.extend(pre_assigned)
    all_edges.sort(key=lambda x: x[2])

    mst_weight = 0
    count = 0

    for w, u, v in all_edges:
        if union(u, v):
            mst_weight += w
            count += 1
            if count == n - 1:
                break

    return str(mst_weight)


