def get_gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solution(input_str):
    data = input_str.strip().split()
    ptr = 0

    n = int(data[ptr]); ptr += 1
    m = int(data[ptr]); ptr += 1

    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(data[ptr]); ptr += 1
        v = int(data[ptr]); ptr += 1
        w = int(data[ptr]); ptr += 1
        adj[u].append((v, w))

    q = int(data[ptr]); ptr += 1
    queries = []
    for _ in range(q):
        v = int(data[ptr]); ptr += 1
        s = int(data[ptr]); ptr += 1
        t = int(data[ptr]); ptr += 1
        queries.append((v, s, t))

    visited = set()
    dist = {}
    par = {}
    global_gcd = 0

    def dfs(u, d):
        visited.add(u)
        dist[u] = d
        for v, w in adj[u]:
            if v not in visited:
                par[v] = u
                dfs(v, d + w)
            else:
                if v != par.get(u):
                    cycle_len = d + w - dist.get(v, 0)
                    nonlocal global_gcd
                    global_gcd = get_gcd(global_gcd, cycle_len)

    results = []

    # Process each connected component to find cycle gcd
    for i in range(1, n + 1):
        if i not in visited:
            dfs(i, 0)

    # Process each query
    for v, s, t in queries:
        if t == 1:
            # Modulo 1 is always 0
            results.append("YES")
        else:
            if global_gcd == 0:
                # No cycles, need s % t == 0 (L = 0)
                results.append("YES" if s % t == 0 else "NO")
            else:
                # Need L ≡ -s (mod t) where L is representable by cycle lengths
                # L must be divisible by global_gcd
                # Check if the required value is compatible with modular constraints
                required_rem = (-s) % t
                if required_rem % get_gcd(global_gcd, t) == 0:
                    results.append("YES")
                else:
                    results.append("NO")

    return "\n".join(results)

