import sys

# Increase recursion depth for deep nested expressions
sys.setrecursionlimit(200000)

MOD = 10**9 + 7

class ConcatResult:
    """Represents a number with its actual digit length and value modulo MOD"""
    def __init__(self, length, value):
        self.length = length
        self.value = value % MOD

    def concat(self, other, mod):
        """Concatenate two numbers: if A has length L and other has length M,
        result is A * 10^M + other"""
        new_value = (self.value * pow(10, other.length, mod) + other.value) % mod
        return ConcatResult(self.length + other.length, new_value)

def digit_length(n):
    """Number of digits in n"""
    return len(str(n))

def parse_range(start, end, mod):
    """Concatenate all numbers from start to end (inclusive)"""
    if start > end:
        return ConcatResult(0, 0)

    result = ConcatResult(digit_length(start), start)

    for i in range(start + 1, end + 1):
        d = digit_length(i)
        result = result.concat(ConcatResult(d, i), mod)

    return result

def parse_number(s, pos):
    """Parse a number from position pos, return (value, new pos)"""
    start = pos
    while pos < len(s) and s[pos].isdigit():
        pos += 1
    if start == pos:
        return 0, start
    return int(s[start:pos]), pos

def parse_expr(s):
    """Parse the main expression"""
    pos = 0
    n = len(s)

    def parse_term():
        nonlocal pos
        # Parse number(s) with possible '-' separators for range
        num, pos = parse_number(s, pos)
        if num == 0:
            return ConcatResult(0, 0), pos

        # Check for range: num - num
        if pos < n and s[pos] == '-':
            pos += 1
            right, pos = parse_number(s, pos)
            if right > num:
                num = parse_range(num, right, MOD)

        # Check for nested expression: num ( expression )
        if pos < n and s[pos] == '(':
            pos += 1  # consume '('
            sub, pos = parse_expr()
            if pos < n and s[pos] == ')':
                pos += 1  # consume ')'

            # Repeat concatenation
            result = ConcatResult(num.length, num.value)
            if sub.length > 0:
                for _ in range(num.value):
                    result = result.concat(sub, MOD)
            return result, pos

        return ConcatResult(num, num), pos

    # Parse: term | term + term | term + term + ...
    left, pos = parse_term()
    while pos < n and s[pos] == '+':
        pos += 1
        right, pos = parse_term()
        left = left.concat(right, MOD)

    return left.value

def solution(s):
    """Main solution function"""
    s = s.strip()
    if not s:
        return "0"
    return str(parse_expr(s))

