    x = int(parts[1])
    n = int(parts[2])
    m = int(parts[3])

    def count_ac(s):
        cnt = 0
        for i in range(len(s) - 1):
            if s[i] == 'A' and s[i+1] == 'C':
                cnt += 1
        return cnt

    def build_sk(s1, s2, k):
        if k <= 2:
            return s1 if k == 1 else s2
        seq = [s1, s2]
        for _ in range(k - 2):
            seq.append(seq[-2] + seq[-1])
        return seq[-1]

    candidates = []

    for i1 in range(n + 1):
        for i2 in range(n + 1):
            s1 = 'A' * i1 + 'C' * (n - i1) if i1 >= 0 and n >= 0 else 'AC' * ((n+1)//2)
            for j1 in range(m + 1):
                s2 = 'A' * j1 + 'C' * (m - j1) if j1 >= 0 and m >= 0 else 'AC' * ((m+1)//2)
                s1 = 'A' * i1 + 'C' * (n - i1)
                s2 = 'A' * j1 + 'C' * (m - j1)
                if len(build_sk(s1, s2, k)) < 5000:
                    candidates.append((s1, s2))

    for s1, s2 in candidates:
        try:
            sk = build_sk(s1, s2, k)
            ac = count_ac(sk)
            if ac == x:
                return f"{s1}\n{s2}\n"
        except:
            continue

    # Try more focused patterns
    patterns_s1 = []
    for i in range(n + 1):
        patterns_s1.append(f'A{i}C{n-i}'.replace('0', ''))

    patterns_s2 = []
    for j in range(m + 1):
        patterns_s2.append(f'A{j}C{m-j}'.replace('0', ''))

    for s1 in patterns_s1:
        s1 = 'A' * s1.count('A') + 'C' * s1.count('C')
        for s2 in patterns_s2:
            s2 = 'A' * s2.count('A') + 'C' * s2.count('C')
            try:
                sk = build_sk(s1[:n], s2[:m], k)
                ac = count_ac(sk)
                if ac == x:
                    return f"{s1[:n]}\n{s2[:m]}\n"
            except:
                continue

    return "Happy new year!\n"


